DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030131834_ChequeBatchGlPosting') THEN
    CREATE TABLE "ADM_PRODUCT_ACTIONS" (
        "PRODUCT_ACTION_ID" bigint GENERATED BY DEFAULT AS IDENTITY,
        "PRODUCT_ID" bigint NOT NULL,
        "ACTION_CODE" character varying(50) NOT NULL,
        "PRODUCT_EVENT_RULE_ID" bigint,
        "IS_ACTIVE" boolean NOT NULL,
        "CREATED_BY" character varying(100) NOT NULL,
        "CREATED_AT" timestamp with time zone NOT NULL,
        "UPDATED_BY" character varying(100),
        "UPDATED_AT" timestamp with time zone,
        "ROW_VERSION" integer NOT NULL,
        CONSTRAINT "PK_ADM_PRODUCT_ACTIONS" PRIMARY KEY ("PRODUCT_ACTION_ID"),
        CONSTRAINT "FK_ADM_PRODUCT_ACTIONS_ADM_PRODUCTS" FOREIGN KEY ("PRODUCT_ID") REFERENCES "ADM_PRODUCTS" ("PRODUCT_ID") ON DELETE RESTRICT,
        CONSTRAINT "FK_ADM_PRODUCT_ACTIONS_ADM_PRODUCT_EVENT_RULES" FOREIGN KEY ("PRODUCT_EVENT_RULE_ID") REFERENCES "ADM_PRODUCT_EVENT_RULES" ("PRODUCT_EVENT_RULE_ID") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
