        "MODULE_CODE" character varying(3) NOT NULL,
        "YEAR_NO" integer NOT NULL,
        "APP_CODE" character varying(10) NOT NULL,
        "MODULE_NAME_EN" character varying(200) NOT NULL,
        "MODULE_NAME_AR" character varying(200),
        "LAST_NO" bigint NOT NULL,
        "DIGITS" integer NOT NULL,
        "IS_ACTIVE" boolean NOT NULL,
        "CREATED_BY" character varying(100) NOT NULL,
        "CREATED_AT" timestamp with time zone NOT NULL,
        "UPDATED_BY" character varying(100),
        "UPDATED_AT" timestamp with time zone,
        "ROW_VERSION" integer NOT NULL,
        CONSTRAINT "PK_GL_TRAN_SET_SEQUENCES" PRIMARY KEY ("MODULE_CODE", "YEAR_NO")
    );
    END IF;
END $EF$;

DO $EF$
